mapper.select:
SELECT * FROM ( SELECT rownum rnum, a.* FROM ( SELECT * FROM ( SELECT PROD_ID as prodId, PROD_NAME as name, PROD_PRICE as price, IMAGE_URL as imageUrl, ORIGIN_URL as originUrl, SOURCE as source, BOARD_TYPE as boardType, REG_DATE as regDate FROM Common_Product WHERE 1=1
AND PROD_NAME LIKE '%'||#{keyword}||'%'
UNION ALL
SELECT DEAL_ID as prodId, TITLE as name, CURRENT_PRICE as price, IMAGE_URL as imageUrl, ORIGIN_URL as originUrl, COMMUNITY_NAME as source, 'HOT' as boardType, LAST_UPDATE_DATE as regDate FROM TB_HOTDEAL_TRACKER WHERE 1=1
AND TITLE LIKE '%'||#{keyword}||'%'
) ORDER BY regDate DESC ) a WHERE rownum <= #{pageEnd} ) WHERE rnum >= #{pageStart}

SELECT ( SELECT COUNT(*) FROM Common_Product WHERE 1=1
AND PROD_NAME LIKE '%'||#{keyword}||'%'
) + ( SELECT COUNT(*) FROM TB_HOTDEAL_TRACKER WHERE 1=1
AND TITLE LIKE '%'||#{keyword}||'%'
) FROM DUAL

SELECT PROD_ID 
FROM Common_Product 
WHERE PROD_CODE = #{prodCode}
